    // Legacy clearance fits retain their measured fallback; translated grips keep their authored size when unmeasured.
    private static readonly float[] FallbackScales =
        { 1.48f, 1.86f, 1.82f, 1.00f, 1.84f, 1.00f, 1.00f, 1.76f, 1.92f, 1.00f, 1.68f, 1.00f, 1.92f, 1.64f, 1.00f };

    internal static bool TryGetScale(string handModel, int appearanceId, out float scale)
    {
        scale = 1f;
        if (appearanceId is < 107 or > 121)
            return false;

        var index = appearanceId - 107;
        scale = !string.IsNullOrWhiteSpace(handModel) && HandScales.TryGetValue(handModel, out var factors)
            ? factors[index]
            : FallbackScales[index];
        return true;
    }
}
